import { existsSync } from 'node:fs';
import { resolve } from 'node:path';

/**
 * Loads `.env` files from the API directory into `process.env` without overriding variables
 * that are already set. `.env.local` (personal overrides) wins over `.env` (generated by
 * `npm run env:sync`).
 */
export function loadEnvFiles(directory: string = process.cwd()): void {
  for (const file of ['.env.local', '.env']) {
    const path = resolve(directory, file);
    if (existsSync(path)) {
      process.loadEnvFile(path);
    }
  }
}
